using AfriWallet.Merchants.Intelligence.Api.Contracts;using AfriWallet.Merchants.Intelligence.Application.Abstractions;using AfriWallet.Merchants.Intelligence.Application.Policies;using AfriWallet.Merchants.Intelligence.Application.Services;using AfriWallet.Merchants.Intelligence.Infrastructure;var builder=WebApplication.CreateBuilder(args);builder.Services.AddSingleton<IMerchantIntelligenceSource,SandboxMerchantIntelligenceSource>();builder.Services.AddSingleton<IMerchantIntelligenceRepository,InMemoryMerchantIntelligenceRepository>();builder.Services.AddSingleton<IMerchantIntelligenceAuditStore,InMemoryMerchantIntelligenceAuditStore>();builder.Services.AddSingleton<IMerchantIntelligenceClock,SystemMerchantIntelligenceClock>();builder.Services.AddSingleton<MerchantRiskPolicy>();builder.Services.AddSingleton<MerchantIntelligenceService>();var app=builder.Build();const string Actor="afriwallet-merchant-intelligence-system";app.MapGet("/health",()=>Results.Ok(new{status="Healthy",delivery="AFW-DLV-0019.6",merchantRiskScoring=true,commerceIntelligence=true,deterministic=true,explainable=true,automaticMerchantBlocking=false,automaticMerchantSuspension=false,automaticSettlementFreeze=false,automaticPayoutFreeze=false,paymentCapturePerformed=false,moneyMovementPerformed=false,ledgerMutationPerformed=false}));app.MapPost("/api/v1/merchant-intelligence/evaluate",async(EvaluateMerchantRiskRequest request,MerchantIntelligenceService service,CancellationToken ct)=>Results.Ok(await service.EvaluateAsync(new EvaluateMerchantRiskCommand(request.MerchantId,Actor),ct)));app.MapGet("/api/v1/merchant-intelligence/{merchantId}",async(string merchantId,IMerchantIntelligenceRepository repository,CancellationToken ct)=>{var result=await repository.GetLatestAsync(merchantId,ct);return result is null?Results.NotFound():Results.Ok(result);});app.Run();
